'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const assets={original:'../assets/original.webp',refined:'../assets/refined.webp',reference:'../assets/reference.webp',result:'../assets/result.webp'};
const state={product:'',original:'',ref:'',refined:'',confirmed:false,result:'',demo:false,busy:false,versions:[],mask:null};
let timer;
function say(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',6000)}
function img(target,src,alt){const el=$(target);el.replaceChildren();if(src){const i=new Image();i.src=src;i.alt=alt;el.append(i)}else{const s=document.createElement('span');s.className='upload-placeholder';s.textContent='＋ '+alt;el.append(s)}}
function render(){const result=!!state.result;$('#workspace').className='workspace '+(result?'is-result':'is-setup');img('#thumb',state.product,'上传商品图片');img('#refPreview',state.ref,'上传风格参考图（选填）');$('#cutoutStatus').textContent=state.confirmed?'已确认':state.refined?'待确认':state.product?'已上传':'等待上传';$('#refState').textContent=state.ref?'已上传':'选填';$('#retouchBtn').disabled=!state.product||state.busy;$('#retouchBtn').textContent='精修商品';$('#manualMask').disabled=!state.product||state.busy;$('#confirmBtn').disabled=!state.product||state.busy;$('#confirmBtn').textContent=state.confirmed?'商品已确认':'确认商品';$('#retouchPanel').classList.toggle('hidden',!state.refined);if(state.refined)$('#retouchedPreview').src=state.refined;$('#confirmMask').disabled=!state.product||state.busy;$('#confirmMask').checked=state.confirmed;$('#generate').disabled=!state.product||!state.confirmed||state.busy;$('#generate').textContent=state.busy?'正在处理…':'生成宣传图';$('#formHint').textContent=!state.product?'先上传商品图片；参考图可选，也可以直接输入场景描述。':!state.confirmed?'精修并检查商品后，点击「确认商品」。':'商品已确认，可以生成宣传图。';$('#demoNotice').classList.toggle('hidden',!state.demo);$('#result').classList.toggle('hidden',!result);$('#emptyArt').classList.toggle('hidden',result);if(result)$('#result').src=state.result;$('#projectTitle').textContent='商品场景图';$('#originalBtn').disabled=!state.original;$('#selectRegion').classList.add('hidden');$$('.steps .step').forEach((e,i)=>e.classList.toggle('active',i===(result?3:state.confirmed?2:state.product?1:0)));$$('#options button').forEach(b=>b.disabled=!result||state.busy);['feedback','interpretBtn','revise','checkBtn'].forEach(id=>$('#'+id).disabled=!result||state.busy);$('#exportBtn').classList.toggle('hidden',!result);$('#exportBtn').href=result?state.result:'#';$('#exportBtn').download='商品场景宣传图.png';}
async function busy(fn,label){if(state.busy)return;state.busy=true;$('#jobStatus').classList.remove('hidden');$('#jobStatus').textContent=label;render();try{await fn()}catch(e){say(e.message)}finally{state.busy=false;$('#jobStatus').classList.add('hidden');render()}}
async function dataURL(src){return new Promise((resolve,reject)=>{const im=new Image();im.crossOrigin='anonymous';im.onload=()=>{try{const c=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(im.width,im.height));c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.82))}catch{reject(Error('图片读取失败，请重新上传商品图'))}};im.onerror=()=>reject(Error('图片加载失败，请重试'));im.src=src})}
async function api(action,images,prompt){const base=window.COMMERCE_API_BASE||'';if(location.hostname==='sherinelee.github.io'&&!base)throw Error('图片处理服务尚未连接，你可以先体验示例流程；上传的图片仍保留在当前页面。');const r=await fetch(base+'/api/commerce',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,images:await Promise.all(images.filter(Boolean).map(dataURL)),prompt,width:$('#widthInput').value,height:$('#heightInput').value})});let d;try{d=await r.json()}catch{throw Error('图片服务暂时不可用，请使用体验示例或稍后重试')}if(!r.ok)throw Error(d.error||'处理失败');return d}
async function pick(kind){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=()=>{const file=input.files[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)){say('请选择 PNG、JPG 或 WebP 图片');return}if(file.size>20e6){say('请选择小于20MB的图片');return}const url=URL.createObjectURL(file),im=new Image();im.onerror=()=>{URL.revokeObjectURL(url);say('图片无法读取，请换一张图片')};im.onload=async()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(im.width,im.height));canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const src=canvas.toDataURL('image/jpeg',.82);URL.revokeObjectURL(url);state.demo=false;if(kind==='product'){Object.assign(state,{original:src,product:src,refined:'',confirmed:false,result:'',mask:null});render()}else{state.ref=src;render();await analyze()}};im.src=url};input.click()}
async function analyze(){await busy(async()=>{if(state.demo){$('#background').value='浅色木桌上，粉米色调，柔和自然光，绿植点缀，浅色织物的家居氛围';return}const d=await api('analyze',[state.ref]);$('#background').value=d.text},'正在识别参考图…')}
$('#uploadBtn').onclick=()=>pick('product');$('#refBtn').onclick=()=>pick('ref');$('#demoBtn').onclick=()=>{Object.assign(state,{demo:true,original:assets.original,product:assets.original,ref:assets.reference,refined:'',confirmed:false,result:'',mask:null});$('#background').value='浅色木桌，粉米色调，柔和自然光，绿植点缀';render();say('已载入发圈示例，请先精修商品')};
$('#retouchBtn').onclick=()=>busy(async()=>{if(state.demo){await new Promise(r=>setTimeout(r,850));state.refined=assets.refined}else{const d=await api('retouch',[state.original]);if(!d.image)throw Error('未返回精修图片，请重试');state.refined=d.image}state.product=state.refined;state.confirmed=false;say('请核对商品颜色、纹样、文字和边缘，再确认商品')},'正在精修商品…');
$('#acceptRetouch').onclick=()=>{state.product=state.refined;state.confirmed=false;render()};$('#keepOriginal').onclick=()=>{state.product=state.original;state.confirmed=false;render()};$('#confirmBtn').onclick=()=>{state.confirmed=true;render();say('商品已确认，可以生成宣传图')};$('#confirmMask').onchange=e=>{state.confirmed=e.target.checked;render()};
function preview(){const d=document.createElement('dialog');d.className='compare-dialog';const box=document.createElement('div');box.className='comparison';for(const [src,name]of [[state.original,'原图'],[state.refined||state.product,'当前商品']]){const section=document.createElement('section'),p=document.createElement('p'),i=new Image();p.textContent=name;i.src=src;i.alt=name;section.append(p,i);box.append(section)}const b=document.createElement('button');b.textContent='关闭';b.onclick=()=>d.close();d.append(box,b);document.body.append(d);d.onclose=()=>d.remove();d.showModal()}
$('#compareRetouch').onclick=preview;$('#originalBtn').onclick=preview;$('#originalSetup').onclick=preview;
let brushCanvas,painting=false;const canvas=$('#maskCanvas'),ctx=canvas.getContext('2d');
$('#manualMask').onclick=()=>{if(!state.product)return;const im=new Image();im.crossOrigin='anonymous';im.onload=()=>{canvas.width=im.width;canvas.height=im.height;ctx.drawImage(im,0,0);brushCanvas=document.createElement('canvas');brushCanvas.width=im.width;brushCanvas.height=im.height;$('#maskDialog').showModal()};im.onerror=()=>say('图片读取失败，请重试');im.src=state.product};
function paint(e){if(!painting)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*canvas.width/r.width,y=(e.clientY-r.top)*canvas.height/r.height,radius=Number($('#brushSize').value)*canvas.width/r.width;for(const [c,color]of [[ctx,'rgba(40,92,224,.3)'],[brushCanvas.getContext('2d'),'white']]){c.fillStyle=color;c.beginPath();c.arc(x,y,radius,0,Math.PI*2);c.fill()}}
canvas.onpointerdown=e=>{painting=true;canvas.setPointerCapture(e.pointerId);paint(e)};canvas.onpointermove=paint;canvas.onpointerup=()=>painting=false;canvas.onpointercancel=()=>painting=false;
$('#saveMask').onclick=async()=>{const m=brushCanvas.getContext('2d').getImageData(0,0,brushCanvas.width,brushCanvas.height);if(!m.data.some((v,i)=>i%4===3&&v)){say('请先涂抹需要保留的商品区域');return}const im=new Image();im.crossOrigin='anonymous';im.onload=()=>{const output=document.createElement('canvas');output.width=im.width;output.height=im.height;const c=output.getContext('2d');c.drawImage(im,0,0);c.globalCompositeOperation='destination-in';c.drawImage(brushCanvas,0,0);state.product=output.toDataURL('image/png');state.mask=state.product;state.confirmed=false;$('#maskDialog').close();render();say('已保留涂抹区域，请检查边缘并确认商品')};im.src=state.product};
$('#ratios').onclick=e=>{const b=e.target.closest('[data-ratio]');if(!b)return;$$('#ratios button').forEach(x=>x.classList.toggle('selected',x===b));const [w,h]=b.dataset.ratio.split(':').map(Number);$('#widthInput').value=w===h?1024:w>h?1024:768;$('#heightInput').value=w===h?1024:w>h?768:1024};
function validateSize(){const w=Number($('#widthInput').value),h=Number($('#heightInput').value);if(!Number.isInteger(w)||!Number.isInteger(h)||w<512||h<512||w>2048||h>2048)throw Error('宽高请填写512至2048之间的整数');return[w,h]}
$('#generate').onclick=()=>busy(async()=>{const[w,h]=validateSize();if(state.demo){await new Promise(r=>setTimeout(r,1100));state.result=assets.result;$('#caption').textContent='体验示例 · 预置成片'}else{const prompt='第一张图片为商品，第二张（如有）仅供场景风格参考。生成商品场景宣传图，保留商品文字、Logo、纹样、主色和轮廓。场景：'+($('#background').value||'简洁自然光桌面，突出商品')+'。主标题：'+$('#titleInput').value+'。副标题：'+$('#subtitleInput').value;const d=await api('generate',[state.product,state.ref],prompt);if(!d.image)throw Error('未返回图片，请重试');state.result=d.image;$('#caption').textContent='请核对商品细节后导出'}state.versions.push(state.result);$('#art').style.aspectRatio=w+'/'+h;$('#artTitle').textContent='';renderVersions();window.scrollTo({top:0,behavior:'smooth'})},state.demo?'正在准备示例效果…':'正在生成宣传图…');
function renderVersions(){const el=$('#versions');el.replaceChildren();state.versions.forEach((url,i)=>{const b=document.createElement('button');b.textContent='版本 '+(i+1);b.onclick=()=>{state.result=url;render()};el.append(b)})}
let instruction='';$('#options').onclick=e=>{const b=e.target.closest('[data-edit]');if(!b)return;instruction=b.dataset.edit;$('#editSummary').textContent=instruction};$('#interpretBtn').onclick=()=>{instruction=$('#feedback').value.trim();$('#editSummary').textContent=instruction?'调整背景：'+instruction+'；保持商品细节。':'请先描述希望调整的地方'};$('#revise').onclick=()=>busy(async()=>{if(!instruction)throw Error('请先选择或填写调整方向');if(state.demo){await new Promise(r=>setTimeout(r,800));say('示例展示改稿流程，成片使用预置图片');return}const d=await api('revise',[state.result,state.product],'修改第一张场景图：'+instruction+'。第二张为真实商品，保持商品细节不变。');if(!d.image)throw Error('未返回改稿图片');state.result=d.image;state.versions.push(d.image);renderVersions()},'正在调整画面…');
$('#checkBtn').onclick=()=>busy(async()=>{if(state.demo){$('#checkResult').textContent='示例检查提示：请对照原图核对颜色、标签文字、格纹与轮廓。';return}const d=await api('check',[state.original,state.result]);$('#checkResult').textContent=d.text},'正在对比商品…');
$$('[data-check]').forEach(el=>el.onchange=()=>{$('#checksHint').textContent=$$('[data-check]').every(x=>x.checked)?'检查完成，可以下载。':'请核对三项商品细节后下载。'});
$('#exportBtn').onclick=async e=>{e.preventDefault();try{const r=await fetch(state.result);if(!r.ok)throw Error();const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='商品场景宣传图.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}catch{say('下载失败，请稍后重试')}};
$('#backToSetup').onclick=()=>{state.result='';render();window.scrollTo({top:0,behavior:'smooth'})};
render();
